'use strict';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:2}).format(n||0);
const clone=x=>JSON.parse(JSON.stringify(x));
let activeAccount=null,savedAccounts=[],accountSaveQueue=Promise.resolve(),accountSwitching=false;
let modelRevision=null,bosses=[],catalog=[],byId={},roster=[],defaults={},demo=[],cubes=[],report=null,job=null,editing=null,revision=0,reportRevision=-1,jobRevision=0,source='No roster loaded';
async function api(path,body){if(activeAccount&&/^history(?:\/|\?|$)/.test(path))path+=(path.includes('?')?'&':'?')+'account_id='+encodeURIComponent(activeAccount);if(activeAccount&&['search','manual'].includes(path))body={...body,account_id:activeAccount};const r=await fetch('/api/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let d;try{d=await r.json()}catch{throw Error('The local app did not return a valid response. Restart Raid Lab.')}if(!r.ok)throw Error(d.error||'Request failed');return d}
function notice(text,error=false){$('notice').textContent=text;$('notice').className=error?'error':''}
function save(){const creating=!activeAccount;if(creating)activeAccount='custom';const snapshot={account_id:activeAccount,roster:clone(roster),source};accountSaveQueue=accountSaveQueue.catch(()=>{}).then(()=>creating?api('accounts/import',{data:{...snapshot,account_name:'Custom roster'}}):api('accounts/save',snapshot)).then(()=>listAccounts()).catch(e=>{notice('Account could not be saved: '+e.message,true);throw e;});accountSaveQueue.catch(()=>{});}
async function listAccounts(){savedAccounts=(await api('accounts')).accounts;$('accountSelect').textContent=(savedAccounts.find(a=>a.id===activeAccount)?.name||'Select account')+' ▾';$('accountMenu').innerHTML=savedAccounts.length?savedAccounts.map(a=>`<div class="account-row"><button class="account-choice" data-account="${esc(a.id)}" aria-pressed="${a.id===activeAccount}">${esc(a.name)} <small>${a.count} units</small></button><button class="account-delete" data-delete="${esc(a.id)}" aria-label="Delete ${esc(a.name)}" title="Delete account and cached data"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg></button></div>`).join(''):'<p>No saved accounts</p>';}
function closeAccountMenu(){$('accountMenu').hidden=true;$('accountSelect').setAttribute('aria-expanded','false');}
async function deleteAccount(id){if(accountSwitching||working||accountRefreshing){notice('Finish or cancel the current operation before deleting an account.',true);return;}const name=savedAccounts.find(a=>a.id===id)?.name||'this account';if(!confirm(`Delete ${name}? Its roster, cached details and recommendation history will be removed from Raid Lab.`))return;accountSwitching=true;$('accountSelect').disabled=true;closeAccountMenu();try{await accountSaveQueue;await api('accounts/delete',{account_id:id});localStorage.removeItem('raid-lab-v1');localStorage.setItem('raid-lab-accounts-migrated','1');await listAccounts();if(activeAccount===id){if(savedAccounts.length)await useAccount(await api('accounts/'+savedAccounts[0].id));else{activeAccount=null;roster=[];source='No roster loaded';revision++;report=null;reportRevision=-1;historyUI.reset();$('resultContent').innerHTML='';$('emptyResults').hidden=false;$('resultsCount').textContent='0';$('searchActivity').hidden=true;localStorage.removeItem('raid-lab-active-account');renderRoster();switchTab('roster');await listAccounts();}}notice(`Deleted ${name} and its cached data and history.`);}catch(e){notice(e.message,true);}finally{accountSwitching=false;$('accountSelect').disabled=false;}}

async function useAccount(fresh){activeAccount=fresh.account_id;roster=clone(fresh.roster);source=fresh.source||fresh.account_name;revision++;report=null;reportRevision=-1;$('resultContent').innerHTML='';$('emptyResults').hidden=false;$('resultsCount').textContent='0';$('searchActivity').hidden=true;$('search').value='';$('tagFilter').value='';historyUI.reset();renderRoster();switchTab('roster');localStorage.setItem('raid-lab-active-account',activeAccount);await listAccounts();notice(`Loaded ${fresh.account_name}: ${roster.length} owned units.`);}
async function switchAccount(id){if(accountSwitching||working||accountRefreshing){$('accountSelect').value=activeAccount;notice('Finish or cancel the current operation before switching accounts.',true);return;}accountSwitching=true;$('accountSelect').disabled=true;try{await accountSaveQueue;await useAccount(await api('accounts/'+encodeURIComponent(id)));}catch(e){$('accountSelect').value=activeAccount;notice(e.message,true);}finally{accountSwitching=false;$('accountSelect').disabled=false;}}
async function initAccounts(){await listAccounts();const legacy=JSON.parse(localStorage.getItem('raid-lab-v1')||'null');if(!localStorage.getItem('raid-lab-accounts-migrated')&&legacy?.roster?.length){if(legacy.source?.startsWith('BlaBlaLink')&&savedAccounts.some(a=>a.id==='my-account'))await api('accounts/save',{account_id:'my-account',...legacy});else await api('accounts/import',{data:legacy,name:'Previously loaded roster'});localStorage.setItem('raid-lab-accounts-migrated','1');localStorage.removeItem('raid-lab-v1');await listAccounts();}const wanted=localStorage.getItem('raid-lab-active-account');const id=savedAccounts.find(a=>a.id===wanted)?.id||savedAccounts[0]?.id;if(id)await useAccount(await api('accounts/'+id));else renderRoster();}
function changed(){revision++;save();renderRoster();if(report)renderReport()}
const feedbackUI=RaidFeedback.create({api,getRoster:()=>roster,getCatalog:()=>byId});
const historyUI=RaidHistory.create({feedback:feedbackUI.open,root:$('historyView'),api,getCatalog:()=>byId,download,checks:squadCheckItems,getModelRevision:()=>modelRevision});
function switchTab(name){for(const n of ['roster','results','history']){$(n+'View').hidden=n!==name;$(n+'Tab').classList.toggle('active',n===name);$(n+'Tab').setAttribute('aria-pressed',n===name)}if(name==='history')historyUI.show()}
function settings(){const out={};for(const k of ['cpu_workers','duration','cover_seconds','level','budget','cp_deficit'])out[k]=Number($(k).value);for(const k of ['gpu_device','compute_mode','boss_simulation','kraken_target_policy','boss_attack_choice','boss_part_policy','content_mode','campaign_objective','boss_id','museum_mode','cover_mode','cover_windows_text','invulnerable_windows_text','element','playstyle'])out[k]=$(k).value;for(const k of ['cdr','healing','fixed_level','require_critical_parts'])out[k]=$(k).checked;return out}
function selectBossLibrary(preferred){const mode=$('content_mode').value;const list=bosses.filter(b=>mode==='museum'?b.hall:mode==='solo'?b.raid:mode==='practice'?b.id==='training':b.content===mode);$('boss_id').innerHTML=list.map(b=>`<option value="${esc(b.id)}">${b.hall?'Hall '+b.hall+' · ':b.raid?'#'+b.raid+' · ':''}${esc(b.name)}</option>`).join('');if(list.some(b=>b.id===preferred))$('boss_id').value=preferred;updateBoss()}
function updateBoss(){const p=bosses.find(b=>b.id===$('boss_id').value);if(!p)return;applyBossElement(p);const criticalAvailable=p.critical_part_deadlines&&(p.id!=='anomaly-kraken'||$('boss_simulation').value==='automatic');$('criticalPartsOption').hidden=!criticalAvailable;if(!criticalAvailable)$('require_critical_parts').checked=false;$('bossChoiceLabel').hidden=!p.attack_choices;$('bossPartLabel').hidden=!p.automatic_mechanics||['anomaly-kraken','museum-mother-whale'].includes(p.id);$('krakenOptions').hidden=p.id!=='anomaly-kraken';$('krakenSimulationLabel').hidden=p.id!=='anomaly-kraken';$('krakenPolicyLabel').hidden=p.id!=='anomaly-kraken'||$('boss_simulation').value!=='automatic';const mode=$('content_mode').value,campaign=mode==='campaign';$('museumModeLabel').hidden=!p.hall;$('practiceBuild').hidden=mode!=='practice';$('campaignSettings').hidden=!campaign;$('combatControls').hidden=campaign;$('playstyleLabel').hidden=campaign;$('bossPickerLabel').hidden=campaign;const level=mode==='special'?'Level 200':mode==='anomaly'?'Your levels · capped at 400':mode==='campaign'||(p.hall&&$('museum_mode').value==='no-limit')?'Your unit levels':mode==='practice'?'Practice level':'Level 400';$('bossSummary').innerHTML=`<span class="boss-status">${campaign?'Composition recommendation':p.id==='training'?'Practice reference':p.automatic_mechanics?'Automatic fight simulation':'Mechanics unverified'}</span><h3>${esc(p.name)}</h3><p>${p.weakness==='Any'?(p.id==='training'?'Neutral target':campaign?'Wave clear & team utility':'Enemy element unverified'):esc(p.weakness)+' weakness'} · ${level}</p><small>${campaign?'CP deficit changes effective stats. A boss DPS number cannot predict wave clear.':p.id==='training'?'A stationary target for comparing builds.':p.automatic_mechanics?'Part objectives, interruption targets, attack choices and survival affect each simulated team. Outcomes use an approximate physical model.':'Boss downtime, QTE damage thresholds and survival are not yet calibrated. Results cannot confirm a clear.'}</small>${renderSpecialGuide(p)}`}

function updateUptime(){const exact=$('cover_mode').value==='windows';$('coverWindowsLabel').hidden=!exact;$('cover_seconds').disabled=exact;const duration=Number($('duration').value);let seconds=Number($('cover_seconds').value),valid=Number.isFinite(duration)&&duration>0;if(exact){const parts=$('cover_windows_text').value.split(',').filter(x=>x.trim());const windows=[];for(const part of parts){const m=part.match(/^\s*(\d+(?:\.\d+)?)\s*[-–]\s*(\d+(?:\.\d+)?)\s*$/);if(!m){valid=false;break}const a=Number(m[1]),b=Number(m[2]);if(a>=b||b>duration)valid=false;windows.push([a,b])}windows.sort((a,b)=>a[0]-b[0]);const merged=[];for(const w of windows){if(merged.length&&w[0]<=merged.at(-1)[1])merged.at(-1)[1]=Math.max(w[1],merged.at(-1)[1]);else merged.push(w)}seconds=merged.reduce((sum,w)=>sum+w[1]-w[0],0)}valid=valid&&Number.isFinite(seconds)&&seconds>=0&&seconds<=duration;const pct=valid?100*(duration-seconds)/duration:0;$('uptimeValue').textContent=valid?`${pct.toFixed(1)}% before boss reactions · ${seconds}s planned cover`:'Check cover time and duration';$('uptimeBar').style.width=pct+'%'}
function renderRoster(){
 roster.forEach(r=>{if(byId[r.id]?.supported)r.assumptions=(r.assumptions||[]).filter(n=>n!=='Skill kit not supported; excluded from simulations.');});
 $('source').textContent=source;$('rosterCount').textContent=roster.filter(r=>r.enabled&&byId[r.id]?.supported).length;
 $('emptyRoster').hidden=roster.length>0;$('rosterTable').hidden=!roster.length;
 const query=$('search').value.trim().toLowerCase(),tag=$('tagFilter').value;
 $('rows').innerHTML=roster.map((r,i)=>({r,i,c:byId[r.id]})).filter(({c})=>c&&(!query||[c.name,c.element,c.role,c.weapon,...c.tags].join(' ').toLowerCase().includes(query))&&(!tag||c.tags.includes(tag))).map(({r,i,c})=>`<tr><td><input type="checkbox" data-enable="${i}" ${r.enabled?'checked':''} ${!c.supported?'disabled':''} aria-label="Use ${esc(c.name)}"></td><td><div class="unit-name">${esc(c.name)}</div><div class="unit-meta"><span class="element ${esc(c.element)}"></span>${esc(c.element)} · ${esc(c.weapon)} · ${esc(c.role)}</div><div class="badges">${c.tags.slice(0,3).map(t=>`<span class="badge ${t==='CDR'?'accent':''}">${esc(t)}</span>`).join('')}</div></td><td>B${esc(c.burst)}<div class="unit-meta">${c.cooldown}s</div></td><td>${['1','2','3'].map(k=>r.build.skill_levels[k]).join(' / ')}</td><td><div class="unit-meta">Lv. ${r.build.level} · Core +${r.build.core_enhancement}</div><div class="${!c.supported||r.assumptions.length?'warning':'unit-meta'}">${!c.supported?'Kit unsupported':r.assumptions.length?'Review assumptions':'Custom build'}</div></td><td><button class="quiet" data-edit="${i}">Edit</button></td></tr>`).join('');
 $('coverage').textContent=`${catalog.filter(c=>c.supported).length} skill kits available for simulation · ${catalog.length} characters in the catalogue. All current characters have skill kits, including base and Favorite Item versions.`;
}
function download(filename,obj){const u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function imported(data,name){if(working||accountRefreshing||accountSwitching)throw Error('Finish the current operation before importing an account.');await accountSaveQueue;const d=await api('accounts/import',{data,name});await useAccount(d);notice(`Imported ${d.account_name}: ${roster.length} owned units.`+(d.warnings?.length?' '+d.warnings.join(' '):''));}
function field(id,label,value,min,max,step='1'){return `<label>${label}<input id="e_${id}" type="number" value="${esc(value)}" min="${min}" max="${max}" step="${step}" required></label>`}
function selectField(id,label,value,options){return `<label>${label}<select id="e_${id}">${options.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(value)?'selected':''}>${esc(o[1])}</option>`).join('')}</select></label>`}
function drawEditor(){const r=roster[editing],b=r.build;$('editName').textContent=byId[r.id].name;$('editNotes').textContent=r.assumptions.join(' ')||'Custom build. Double-check all investment before comparing teams.';$('editError').textContent='';
 const total=v=>(Array.isArray(v)?v.reduce((sum,n)=>sum+Number(n),0):Number(v||0)).toFixed(2);
 $('overloadTotals').innerHTML='<h3>Saved Overload totals</h3><p class="muted">Combined across all four gear pieces. Research, cube and skill buffs are separate.</p><p>'+[['max_ammo_pct','Ammo capacity'],['atk_pct','ATK'],['element_bonus','Elemental advantage'],['charge_dmg_pct','Charge damage'],['charge_speed_pct','Charge speed'],['accuracy_pct','Hit rate'],['crit_rate','Critical rate'],['crit_dmg','Critical damage'],['def_pct','DEF']].filter(([k],i)=>i<6||Number(total(b.equip_skills[k]))!==0).map(([k,label])=>esc(label)+': <strong>'+total(b.equip_skills[k])+'%</strong>').join(' · ')+'</p>';
 const parts=[['머리','Head'],['몸통','Body'],['팔','Arms'],['다리','Legs']];
 $('editFields').innerHTML=field('level','Unit level',b.level,1,1000)+field('breakthrough','Limit breaks',b.breakthrough,0,3)+field('core_enhancement','Core enhancement',b.core_enhancement,0,7)+field('affinity','Bond level',b.affinity,1,40)+field('s1','Skill 1',b.skill_levels['1'],1,10)+field('s2','Skill 2',b.skill_levels['2'],1,10)+field('s3','Burst skill',b.skill_levels['3'],1,10)+selectField('favorite_stage','Favorite-item phase',b.favorite_stage,[[0,'None'],[1,'Phase 1'],[2,'Phase 2'],[3,'Phase 3']])+selectField('collection_stage','Collection item',b.collection_stage,[['없음','None'],...['R','SR'].flatMap(r=>Array.from({length:16},(_,i)=>[r+i,r+' · level '+i]))])+selectField('cube','Cube',b.cube.name,[["없음","None equipped"],...cubes.map(c=>[c,({'렐릭 베어 큐브':'Resilience (reload)','택티컬 베어 큐브':'Bastion (ammo refill)','렐릭 어설트 큐브':'Assault (hit rate)','렐릭 부스트 큐브':'Adjutant (charge speed)','택티컬 부스트 큐브':'Onslaught (charge damage)','택티컬 어설트 큐브':'Wingman (ammo capacity)'})[c]||c])])+field('cubeLevel','Cube level',b.cube.level,0,15)+`<div></div>`+parts.map(([p,label],i)=>selectField('gear'+i,label+' gear',b.equipment[p].tier||'기업',[['없음','None'],['기업','Overload'],...Array.from({length:9},(_,j)=>['T'+(j+1),'T'+(j+1)])])+field('gearLv'+i,label+' gear level',b.equipment[p].level||0,0,5)).join('')+`<p class="muted wide">Overload gear uses its level directly. Set T9 manufacturer matching in advanced JSON. Mixed ammo/charge-speed lines are preserved in JSON.</p>`+[['atk_pct','ATK bonus %'],['element_bonus','Element bonus %'],['charge_dmg_pct','Charge damage %'],['crit_rate','Critical rate %'],['crit_dmg','Critical damage %']].map(([k,l])=>field(k,l,b.equip_skills[k]||0,0,1000,'0.01')).join('')+field('common_level','Common research',b.console.common_level,0,1000)+field('class_level','Class research',b.console.class_level,0,1000)+field('company_level','Manufacturer research',b.console.company_level,0,1000);
 $('buildJson').value=JSON.stringify(b,null,2); $('e_cube').onchange=()=>{$('e_cubeLevel').value=$('e_cube').value==='없음'?0:Math.max(1,Number($('e_cubeLevel').value))}
}
function openEditor(i){editing=i;drawEditor();$('editor').showModal()}
async function acceptBuild(b){const r=roster[editing];const d=await api('import',{roster:[{...r,build:b}]});roster[editing]=d.roster[0];changed()}
function renderPicker(){const q=$('pickSearch').value.toLowerCase();$('pickList').innerHTML=catalog.filter(c=>!roster.some(r=>r.id===c.id)&&c.name.toLowerCase().includes(q)).map(c=>`<div class="pick-item"><div><strong>${esc(c.name)}</strong><div class="unit-meta">${esc(c.element)} · B${esc(c.burst)} · ${esc(c.weapon)}${!c.supported?' · Kit unsupported':''}</div></div><button data-add="${catalog.indexOf(c)}">Add</button></div>`).join('')}
function eventLabel(e){if(e.event==='full_burst 시작')return 'FULL BURST';if(e.event==='full_burst 종료')return 'Full Burst ends';const stage=e.event.match(/(?:stage|reenter):(\d)/);return stage?`${e.event.startsWith('reenter')?'Re-enter':'B'}${stage[1]} · ${byId[e.unit]?.name||e.unit}`:e.event}
function renderCombat(fight){if(!fight?.model)return '';return `<section class="support-plan"><h4>${esc(fight.model)}</h4><p>${esc(fight.survival)} · simulated to ${fight.simulated_until}s${fight.phase?` · phase ${fight.phase}`:""}. ${esc(fight.stop_reason||'')}</p><p class="warning">Experimental physical model. This does not verify a clear or a failure in game.</p><details><summary>Interruption checks and boss actions</summary>${fight.checks.map(c=>`<p>${esc(c.id)} · ${esc(c.status)} · ${c.targets.length} targets cleared</p>`).join('')}<div class="burst-list">${fight.events.map(e=>`<span class="burst-event">${e.time}s · ${esc(e.event)}${e.part?' · '+esc(e.part):''}${e.shot?' · attack '+e.shot:''}</span>`).join('')}</div></details><details><summary>Incoming attacks, cover and remaining HP</summary><div class="table-scroll"><table><thead><tr><th>Time</th><th>Unit</th><th>HP damage</th><th>Protection</th><th>Remaining HP</th><th>Cover HP</th></tr></thead><tbody>${fight.incoming.map(e=>`<tr><td>${e.time}s</td><td>${esc(byId[e.target]?.name||e.target)}</td><td>${fmt(e.damage)}</td><td>${esc(e.blocked_by||'None')} ${e.absorbed?fmt(e.absorbed):''}</td><td>${fmt(e.hp)}</td><td>${fmt(e.cover)}</td></tr>`).join('')}</tbody></table></div></details><details><summary>Model assumptions</summary><ul>${fight.assumptions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul></details></section>`}
function renderAimPlan(team){const fight=team.encounter_timeline,plan=fight?.control_plan||[];if(!plan.length&&!team.control_comparison)return '';const unit=fight.off_burst_controller,checks=fight.critical_deadlines||fight.critical_parts||[];return `<section class="support-plan"><h4>Off-burst control: ${esc(byId[unit]?.name||unit)}</h4><p>Aim at the critical part while Full Burst is inactive. During Full Burst, the squad follows your aim.${plan.some(p=>p.focus_fire)?' Active Focus Fire also brings allied weapon fire onto your aim outside Full Burst.':''}</p>${!plan.length?'<p>No off-burst weapon hits reached a part in this simulation.</p>':''}${team.control_comparison?`<p>Compared ${team.control_comparison.length} completed aim-controller simulations with this squad and burst order. ${team.critical_part_requirement?.passed?'Chosen control plan passes the modeled part deadlines.':'No tested controller passed every deadline; this is the highest-damage control option tested.'}</p>`:''}<details><summary>Target timing and control comparison</summary>${plan.map(p=>`<p>${p.start.toFixed(2)}–${p.end.toFixed(2)}s: control ${esc(byId[p.unit]?.name||p.unit)} → ${esc(fight.part_labels?.[p.part]||checks.find(c=>c.id===p.part)?.part||p.part.replaceAll('_',' '))}. ${fmt(p.damage)} targeted weapon damage${p.focus_fire?' including Focus Fire allies':''}.</p>`).join('')}${checks.map(p=>`<p>${esc(p.part)}: ${p.deadline!=null?'deadline '+p.deadline.toFixed(2)+'s':'no attack deadline reached'}; ${p.destroyed_at!=null?'destroyed at '+p.destroyed_at.toFixed(2)+'s':esc(p.status)}.</p>`).join('')}${(team.control_comparison||[]).map(c=>`<p>${esc(byId[c.unit]?.name||c.unit)}: ${c.parts_passed?'part deadlines passed':'part deadlines not passed'} · ${fmt(c.damage)} boss damage.</p>`).join('')}</details></section>`}
let selectedSquad=0,squadReport=null;
function renderReport(){if(!report)return;if(modelRevision&&report.settings?.encounter?.model_revision!==modelRevision)reportRevision=-1;if(squadReport!==report){selectedSquad=0;squadReport=report;}selectedSquad=Math.min(selectedSquad,report.teams.length-1);$('emptyResults').hidden=true;$('resultsCount').textContent=report.teams.length;
 if(report.kind==='campaign'){renderCampaignReport();return}const s=report.settings;let html=report.settings?.encounter?.model_revision!==modelRevision&&modelRevision?'<div class="stale">This report predates the current combat model. Find teams again to update its damage and mechanic checks.</div>':reportRevision!==revision?'<div class="stale">Roster or encounter settings changed. These results use the previous inputs; rerun to update.</div>':'';
 html+=`<div class="panel report-header"><div><p class="eyebrow">${s.boss_simulation==='automatic'?'AUTOMATIC FIGHT · CALIBRATION INCOMPLETE':'DAMAGE REFERENCE · CLEAR NOT VERIFIED'}</p><div class="total">${fmt(report.total)}</div>${report.teams.every(t=>t.damage_accounting)?'<small class="muted">Direct boss damage</small>':''}<p>${report.teams.length} team${report.teams.length>1?'s':''} · ${s.content_mode==='special'?'up to ':''}${s.duration}s each · ${esc(s.encounter?.name||'Legacy training target')} · ${s.uptime??100}% before boss reactions${s.encounter?.hall?' · '+(s.museum_mode==='no-limit'?'No Limit':'Challenge'):''}</p></div><div><button id="exportReport">Export report</button><p>${report.simulations} simulations · ${report.elapsed}s elapsed${report.compute?'<br>'+esc(report.compute.device||'CPU')+' · '+(report.compute.workers||1)+' CPU workers':''}</p></div></div>`;
 if(report.completion?.reason==='cancelled'||report.completion?.returned_teams<report.completion?.requested_teams)html+=`<div class="panel warning"><strong>Best results so far</strong><p>Search stopped with ${report.teams.length} of ${report.completion.requested_teams} requested squads available. These recommendations use completed simulations; remaining candidates were not finished.</p></div>`;
 if(report.selection?.survival_model_stops?.length)html+=`<div class="panel warning"><strong>Team ranking is uncertain</strong><p>${report.selection.survival_model_stops.length} tested burst orders stopped early because of unverified boss survival predictions. Those shortened runs can cause a strong real team to rank too low.</p></div>`;
 if(report.selection?.critical_parts)html+=`<div class="panel ${report.selection.critical_parts.fallback?'warning':''}"><strong>${report.selection.critical_parts.fallback?'Critical-part fallback':'Critical-part requirement met'}</strong><p>${esc(report.selection.critical_parts.message)}</p><small>${esc(report.selection.critical_parts.scope)}</small></div>`;
 html+='<div id="squadDeck" class="squad-deck">';
 if(report.teams.length>1)html+=`<nav class="squad-tabs" role="tablist" aria-label="Squads">${report.teams.map((t,i)=>`<button type="button" role="tab" id="squadTab${i}" aria-controls="squadPanel${i}" aria-selected="${i===selectedSquad}" tabindex="${i===selectedSquad?0:-1}" data-squad="${i}"><span>Squad ${i+1}</span><small>${fmt(t.damage)}</small></button>`).join('')}</nav>`;
 report.teams.forEach((t,i)=>{const max=Math.max(...Object.values(t.breakdown),1),chartMax=Math.max(...t.timeline,1);html+=`<article class="panel squad" id="squadPanel${i}" ${report.teams.length>1?`role="tabpanel" aria-labelledby="squadTab${i}" tabindex="0"`:''} ${i===selectedSquad?'':'hidden'}><div class="squad-head"><div><p class="eyebrow">SQUAD ${String(i+1).padStart(2,'0')}</p><h3>${esc(s.element==='Any'?'Boss damage':s.element+' damage')} · ${t.bursts} Full Bursts</h3></div><div class="score">${fmt(t.damage)}<p class="muted">${t.damage_accounting?'Direct boss damage<br>':''}${fmt(t.dps)} DPS</p></div></div><div class="squad-members">${t.members.map((id,j)=>{const c=byId[id];return `<div class="member"><span class="slot">0${j+1} / B${esc(c.burst)}</span><strong>${esc(c.name)}</strong><small>${t.recommendation?.units?(t.recommendation.units.find(u=>u.id===id)?.burst_times?.length?'Bursts in this rotation':'Off-burst in this simulation'):'Burst usage unavailable'}</small><small><span class="element ${esc(c.element)}"></span>${esc(c.element)} · ${esc(c.weapon)}</small><div class="bar-track"><div class="bar-fill" style="width:${100*(t.breakdown[id]||0)/max}%"></div></div><small>${fmt(t.breakdown[id])} damage</small></div>`}).join('')}</div>${RaidHistory.damageAccounting(t,id=>byId[id]?.name||id)}${renderAimPlan(t)}${renderSpecialOutcome(t)}${renderSquadChecks(t,i)}<div class="squad-foot"><span>${t.team_cdr_activations>0?'Team CDR activated '+t.team_cdr_activations+' times':t.members.some(n=>byId[n].tags.includes('CDR'))?'CDR skill present; check activation':'No team CDR skill'} · ${(t.recommendation?.available_healers||[]).length?'Build supports team healing; strength unverified':'No usable team healing established'}</span><button class="quiet" data-feedback="${i}">Give feedback</button><button class="quiet" data-manual="${i}">Adjust & simulate</button></div>${t.elemental_damage?`<section class="support-plan"><h4>${esc(t.elemental_damage.element)} damage ${t.elemental_damage.assessment==='modeled-barrier'?'through the barrier':'for interruption checks'}</h4><p>${t.elemental_damage.providers.map(n=>esc(byId[n]?.name||n)).join(", ")||"No substantial matching damage dealer"}</p><p>${t.elemental_damage.contributions.map(c=>`${esc(byId[c.id]?.name||c.id)}: ${(c.share*100).toFixed(1)}% of team damage`).join(" · ")}</p><details><summary>How this requirement is checked</summary><p>${esc(t.elemental_damage.criterion)}</p></details></section>`:""}${renderRationale(t)}${renderCombat(t.encounter_timeline)}${t.support_plan?`<section class="support-plan"><h4>Survival & cover plan</h4><p>${esc(t.support_plan.summary)}</p><p>${esc(t.support_plan.cover_policy)}</p><p>${t.support_plan.providers.map(p=>`${esc(byId[p.id].name)}: ${esc(p.roles.join(', '))}`).join(' · ')||'No suggested support roles detected.'}</p>${t.support_plan.policy==='damage-only'?'<p class="warning">Guide support requirements were bypassed.</p>':''}<details><summary>Guidance and confidence</summary><p>${esc(t.support_plan.warning)}</p>${t.support_plan.source?`<a href="${esc(t.support_plan.source)}" target="_blank" rel="noreferrer">${esc(t.support_plan.source_name)} ↗</a>`:''}</details></section>`:''}<div class="mechanic-summary"><strong>${esc(t.mechanics?.status||'Mechanics unverified')}</strong><span>${esc(t.mechanics?.summary||(t.encounter_timeline?.model?"See the modeled outcomes below; gameplay calibration remains incomplete.":"QTE success and surviving the full fight are not established."))}</span><details><summary>Mechanic checks</summary>${(t.mechanics?.checks||[]).map(c=>`<p><strong>${esc(c.name)} · ${esc(c.status)}</strong><br>${esc(c.detail)}</p>`).join('')}</details></div>${t.warnings.map(w=>`<p class="warning">${esc(w)}</p>`).join('')}<details><summary>Damage timeline and burst sequence</summary>${t.timeline.length?`<div class="chart" aria-label="Damage in five-second intervals">${t.timeline.map((v,k)=>`<div title="${k*5}–${(k+1)*5}s: ${Math.round(v).toLocaleString()} damage" class="${(s.cover_windows||[]).some(([a,b])=>a<(k+1)*5&&b>k*5)?'cover-bin':''}" style="height:${Math.max(1,100*v/chartMax)}%"></div>`).join('')}</div><div class="chart-label">Damage per 5 seconds · amber intervals overlap planned cover · hover for values</div>`:''}<div class="burst-list">${t.burst_log.map(e=>`<span class="burst-event ${e.event==='full_burst 시작'?'full':''}">${e.time}s · ${esc(eventLabel(e))}</span>`).join('')}</div></details><details><summary>Exact builds and engine baseline differences</summary><p class="muted">These are the inputs used for this result. Baseline differences are emitted by the upstream engine.</p><pre>${esc(t.deviations)}</pre><pre>${esc(JSON.stringify(t.builds,null,2))}</pre></details></article>`});
 html+=`</div><section class="panel limitations"><h2>How to read this estimate</h2><ul>${[...report.limitations,...report.warnings,...report.assumptions].map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="muted">${s.playstyle==='auto'?'Automatic firing with a modeled 0.5-second burst transition delay.':'One assisted tap shooter, with a modeled 0.1-second burst transition delay.'} ${s.content_mode==='anomaly'?'Unit levels capped at 400.':s.fixed_level?'All units recalculated at level '+s.level+'.':'Unit levels taken from their builds.'}</p></section>`;
 $('resultContent').innerHTML=html;$('exportReport').onclick=()=>download('raid-lab-report.json',report);bindSquadTabs();bindSquadChecks();
}
let working=false,activityTimer=null,activityStarted=0,pollTimer=null,activityFraction=0,activityLimit=120,activityKind='search';
function busy(on){working=on;$('buildBtn').disabled=on;$('buildBtn').textContent=on?'Finding teams…':'Find teams ↗';$('resultsView').setAttribute('aria-busy',String(on));for(const id of ['importBtn','demoBtn','addBtn','testTeam','manualRun'])$(id).disabled=on}
function setActivityProgress(value){activityFraction=Math.max(activityFraction,Math.min(1,Math.max(0,Number(value)||0)));$('activityFill').style.width=(activityFraction*100)+'%';$('activityBar').setAttribute('aria-valuenow',String(Math.round(activityFraction*100)))}
function beginActivity(kind){clearInterval(activityTimer);activityStarted=Date.now();activityKind=kind;activityFraction=0;activityLimit=Number($('budget').value)<=3?120:Number($('budget').value)<=6?240:360;$('searchActivity').hidden=false;$('searchActivity').classList.add('running');$('activityTitle').textContent=kind==='manual'?'Testing your team…':'Finding your teams…';$('activityStage').textContent='Preparing your roster…';$('activityCount').textContent='Preparing candidates';$('activityElapsed').textContent='0s elapsed';$('activityBar').hidden=false;setActivityProgress(0);$('activityBar').setAttribute('aria-valuetext','Preparing search');$('activityHint').textContent=kind==='search'?'The bar tracks the selected search time budget. Search can finish earlier. Cancel to keep the best completed simulations.':'Testing the selected team.';$('cancelBtn').hidden=true;activityTimer=setInterval(()=>{const elapsed=(Date.now()-activityStarted)/1000;$('activityElapsed').textContent=Math.floor(elapsed)+'s elapsed';if(activityKind==='search')setActivityProgress(Math.min(.99,elapsed/activityLimit))},250);$('searchActivity').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})}
function endActivity(title,message,success=false){clearInterval(activityTimer);activityTimer=null;$('searchActivity').classList.remove('running');$('activityTitle').textContent=title;$('activityStage').textContent=message;if(success)setActivityProgress(1);$('activityBar').setAttribute('aria-valuetext',title);$('activityHint').textContent='';$('cancelBtn').hidden=true;busy(false)}
async function start(kind='search',members){if(working||job)return;notice('');busy(true);jobRevision=revision;switchTab('results');beginActivity(kind);$('progress').textContent='Preparing roster…';try{const d=await api(kind,{roster,settings:settings(),members});job=d.id;$('cancelBtn').hidden=false;poll(job)}catch(e){endActivity('Could not start',e.message);$('progress').textContent='Could not start.';notice(e.message,true)}}
async function poll(id){if(!id||job!==id)return;try{const d=await api('jobs/'+id);if(job!==id)return;if(d.status==='running'){const phase=d.phase||'Simulating candidates';$('activityStage').textContent=phase;$('activityCount').textContent=`${d.simulations||0} simulations completed`;if(d.time_limit)activityLimit=d.time_limit;if(d.progress!==undefined)setActivityProgress(d.progress);$('activityBar').setAttribute('aria-valuetext',phase);$('progress').textContent=`${phase} · ${d.simulations||0} simulations`;pollTimer=setTimeout(()=>poll(id),700);return}job=null;if(d.status==='done'){report=d.result;reportRevision=jobRevision;renderReport();historyUI.invalidate();if(report.history_error)notice(report.history_error,true);endActivity(report.completion?.reason==='cancelled'?'Best results so far':'Teams ready',`Returned ${report.teams.length} squad${report.teams.length===1?'':'s'} from ${report.simulations} completed simulations.`,true);$('progress').textContent=`Finished ${report.simulations} simulations in ${report.elapsed}s.`}else if(d.status==='cancelled'){endActivity('Search stopped',d.message||'No team finished a full-fight simulation yet. Your previous results are unchanged.');$('progress').textContent=d.message||'Stopped before any new recommendation was ready.'}else{const message=d.error||'Simulation failed.';endActivity('Simulation stopped',message);notice(message,true);$('progress').textContent='Simulation stopped.'}}catch(e){if(job!==id)return;clearInterval(activityTimer);$('searchActivity').classList.remove('running');$('activityBar').hidden=true;$('activityTitle').textContent='Unable to check progress';$('activityStage').textContent=e.message;$('activityHint').textContent='The simulation may still be running. Cancel it before starting another search.';$('progress').textContent='Connection interrupted.';notice(e.message,true);$('cancelBtn').hidden=false}}
async function cancelSearch(){if(!job)return;const id=job;$('cancelBtn').disabled=true;try{await api('cancel/'+id,{});if(job!==id)return;$('activityStage').textContent='Stopping workers and keeping completed recommendations…';$('progress').textContent='Preparing best results so far…'}catch(e){notice(e.message,true)}finally{$('cancelBtn').disabled=false}}

function openManual(i){const campaign=$('content_mode').value==='campaign';$('manualRun').textContent=campaign?'Assess this team':'Simulate this team';const ids=i<0?roster.filter(r=>byId[r.id].supported).slice(0,5).map(r=>r.id):report.teams[i].members;if(ids.length<5){notice('Add or import at least five units with supported kits to simulate a team.',true);return}$('manualSlots').innerHTML=ids.map((id,j)=>`<label>Slot ${j+1}<select id="m${j}">${roster.filter(r=>byId[r.id].supported).map(r=>`<option value="${esc(r.id)}" ${r.id===id?'selected':''}>${esc(byId[r.id].name)} · B${esc(byId[r.id].burst)}</option>`).join('')}</select></label>`).join('');$('manualError').textContent='';$('manualDialog').showModal()}
