let accountJob=null,accountRefreshing=false;
async function refreshAccount(chooseBrowser=false,profileUrl=null){
 if(accountRefreshing||working||accountSwitching)return;
 try{await accountSaveQueue;}catch(e){notice(e.message,true);return;}
 accountRefreshing=true;$('accountSelect').disabled=true;$('publicProfileBtn').disabled=true;
 const button=$('loadLocalBtn');button.disabled=true;button.textContent='Refreshing account…';
 $('accountCancel').disabled=true;
 $('accountFinish').hidden=true;
 $('accountConnect').disabled=true;$('accountBrowser').disabled=true;
 $('accountConnectionStatus').textContent='Preparing account login…';
 $('accountDialog').showModal();
 try{
  const refresh=await api('account-refresh',{choose_browser:chooseBrowser,profile_url:profileUrl});accountJob=refresh.id;
  $('accountCancel').disabled=false;
  while(true){
   const state=await api('account-refresh/'+refresh.id);
   if(state.status==='needs_browser'&&$('accountBrowser').disabled){
    $('accountBrowser').innerHTML=state.browsers.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('');
    if(state.browsers.some(b=>b.id===state.preferred))$('accountBrowser').value=state.preferred;
    $('accountConnect').disabled=false;$('accountBrowser').disabled=false;
   }
   if(state.status==='running'){
    $('accountConnect').disabled=true;$('accountBrowser').disabled=true;
    if(state.browser)$('accountBrowser').innerHTML=`<option>${esc(state.browser)}</option>`;
   }
   $('accountConnectionStatus').textContent=state.phase||'Fetching your account data…';
   $('accountFinish').hidden=!state.awaiting_close;
   if(state.status==='error')throw Error(state.error);
   if(state.status==='done'){
    const fresh=state.result;await useAccount(fresh);
    notice('Account refreshed from BlaBlaLink at '+new Date(fresh.refreshed_at).toLocaleString()+'. '+roster.length+' owned units. '+(job?'The running simulation keeps its original inputs; rerun afterward to use the refreshed gear. ':'')+(fresh.warnings||[]).join(' '));break;
   }
   notice(state.phase||'Fetching the latest BlaBlaLink account data…');
   await new Promise(resolve=>setTimeout(resolve,1200));
  }
 }catch(e){notice(e.message,true)}finally{accountJob=null;accountRefreshing=false;$('accountCancel').disabled=false;$('accountDialog').close();button.disabled=false;button.textContent='Load my account';$('accountSelect').disabled=false;$('publicProfileBtn').disabled=false;}
}
$('loadLocalBtn').onclick=()=>refreshAccount();
const browserButton=document.createElement('button');browserButton.textContent='Browser…';browserButton.className='quiet';browserButton.title='Choose or change the browser used to refresh your account';$('loadLocalBtn').after(browserButton);browserButton.onclick=()=>{if(accountRefreshing){if(!$('accountDialog').open)$('accountDialog').showModal()}else refreshAccount(true)};
$('accountConnect').onclick=async()=>{
 if(!$('accountBrowser').value){$('accountConnectionStatus').textContent='Choose your browser first.';return;}
 const selected=$('accountBrowser').value;
 $('accountConnect').disabled=true;$('accountBrowser').disabled=true;
 try{
  const d=await api('account-connect',{job:accountJob,browser:selected});
  $('accountConnectionStatus').textContent='Opening '+d.browser+'. Finish BlaBlaLink sign-in, then close the account window to start importing.';
 }catch(e){$('accountConnect').disabled=false;$('accountBrowser').disabled=false;$('accountConnectionStatus').textContent=e.message;}
};
$('accountCancel').onclick=async()=>{try{if(accountJob)await api('account-cancel',{job:accountJob});$('accountDialog').close()}catch(e){$('accountConnectionStatus').textContent=e.message}};
$('accountFinish').onclick=async()=>{const button=$('accountFinish');button.disabled=true;try{await api('account-finish-signin',{job:accountJob})}catch(e){$('accountConnectionStatus').textContent=e.message}finally{button.disabled=false}};
$('accountDialog').addEventListener('cancel',e=>{e.preventDefault();$('accountCancel').click()});

function loadSavedReport(local){if(!['kraken-runtime-v12','mother-whale-runtime-v1','raid-boss-runtime-v1','raid-boss-aim-v2','raid-boss-search-v3',modelRevision].includes(local.report?.settings?.encounter?.model_revision)||!Array.from($('content_mode').options).some(o=>o.value===local.report.settings.content_mode))return;report=local.report;const s=report.settings;$('content_mode').value=s.content_mode;selectBossLibrary(s.boss_id);for(const k of ['compute_mode','duration','cover_seconds','cover_mode','cover_windows_text','invulnerable_windows_text','museum_mode','level','budget','element','playstyle','cp_deficit','campaign_objective','boss_simulation','kraken_target_policy','boss_attack_choice','boss_part_policy'])if(s[k]!==undefined)$(k).value=s[k];for(const k of ['cdr','healing','fixed_level','require_critical_parts'])$(k).checked=s[k];updateBoss();updateUptime();reportRevision=s.encounter?.model_revision===modelRevision?revision:-1;renderReport();switchTab('results')}
$('content_mode').addEventListener('change',()=>selectBossLibrary());$('boss_id').addEventListener('change',updateBoss);$('museum_mode').addEventListener('change',updateBoss);for(const id of ['cover_seconds','duration','cover_mode','cover_windows_text'])$(id).addEventListener('input',updateUptime);

function renderCampaignReport(){const s=report.settings,t=report.teams[0];$('resultContent').innerHTML=`${reportRevision!==revision?'<div class="stale">Inputs changed. Find teams again to update this recommendation.</div>':''}<section class="panel squad"><p class="eyebrow">CAMPAIGN COMPOSITION · CLEAR NOT VERIFIED</p><h2>Your stage team</h2><p>${esc(s.campaign_objective)} · ${s.cp_deficit}% assumed CP deficit · approximately ${s.stat_penalty}% stat penalty</p><div class="squad-members">${t.members.map(id=>`<div class="member"><span class="slot">B${esc(byId[id].burst)} · ${esc(byId[id].weapon)}</span><strong>${esc(byId[id].name)}</strong><small>${esc(byId[id].tags.join(' · '))}</small></div>`).join('')}</div><ul>${t.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><button class="quiet" data-manual="0">Adjust team</button><button id="exportReport">Export report</button><details><summary>Effective stats under this deficit</summary><p>Estimated before combat buffs. This does not validate survival.</p>${t.members.map(id=>`<p>${esc(byId[id].name)} · ATK ${fmt(t.effective_stats[id].atk)} · HP ${fmt(t.effective_stats[id].hp)} · DEF ${fmt(t.effective_stats[id].def)}</p>`).join('')}</details><p class="muted">${report.plans_considered} candidate compositions compared. No stage damage simulation.</p></section><section class="panel limitations"><ul>${[...report.limitations,...report.assumptions].map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`;$('exportReport').onclick=()=>download('raid-lab-campaign.json',report)}


$('computeSettingsBtn').onclick=()=>$('computeDialog').showModal();
function updateComputeVisibility(){$('gpuDeviceLabel').hidden=$('compute_mode').value!=='gpu';$('computeModeSummary').textContent=$('compute_mode').value.toUpperCase()}
function saveComputePreference(){localStorage.setItem('raid-lab-compute-settings',JSON.stringify({mode:$('compute_mode').value,workers:Number($('cpu_workers').value),device:$('gpu_device').value}));updateComputeVisibility()}
async function loadComputeOptions(){try{
 const d=await api('compute');const option=$('compute_mode').querySelector('[value=gpu]');option.disabled=!d.gpu.available;option.textContent=d.gpu.available?'GPU':'GPU · unavailable';
 $('cpu_workers').innerHTML=`<option value="0">Automatic · ${d.cpu_workers} workers</option>`+Array.from({length:d.cpu_worker_limit},(_,i)=>`<option value="${i+1}">${i+1} worker${i?'s':''}</option>`).join('');
 $('gpu_device').innerHTML='<option value="auto">Automatic</option>'+(d.gpu.devices||[]).map((g,i)=>`<option value="${esc(g.id)}">${i+1}. ${esc(g.name)} (${esc(g.backend)})</option>`).join('');
 $('computeHint').textContent=`${d.cpu_available} logical CPUs available. Choose your preferred compute mode and worker limit. GPU availability depends on this machine’s hardware and drivers.`+(!d.gpu.available?' GPU unavailable: '+d.gpu.reason:'');
 let pref;try{pref=JSON.parse(localStorage.getItem('raid-lab-compute-settings')||'null')}catch{}
 if(!pref)pref={mode:localStorage.getItem('raid-lab-compute')||'cpu',workers:0,device:'auto'};
 $('compute_mode').value=pref.mode==='gpu'&&d.gpu.available?'gpu':'cpu';
 $('cpu_workers').value=Number.isInteger(pref.workers)&&pref.workers>=0&&pref.workers<=d.cpu_worker_limit?String(pref.workers):'0';
 $('gpu_device').value=(d.gpu.devices||[]).some(g=>g.id===pref.device)?pref.device:'auto';
 updateComputeVisibility();
 }catch(e){$('compute_mode').value='cpu';$('compute_mode').querySelector('[value=gpu]').disabled=true;$('computeHint').textContent='Hardware detection failed. CPU with automatic workers remains available.';updateComputeVisibility()}}
for(const id of ['compute_mode','cpu_workers','gpu_device'])$(id).addEventListener('change',saveComputePreference);

function renderRationale(t){const r=t.recommendation;if(!r)return '';return `<section class="support-plan"><h4>Why this team</h4>${renderLocalGuidance(t)}${renderKitDependencies(t)}${renderBurstRotation(t)}${r.rationale?`<p>${esc(r.rationale.overview)}</p><p><strong>Boss fit:</strong> ${esc(r.rationale.boss_fit)}</p><p>${esc(r.rationale.allocation_note)}</p><div class="causal-cards">${r.rationale.interactions.map(c=>`<section class="causal-card"><h5>${esc(c.title)}</h5><p>${esc(c.why)}</p><p class="warning">${esc(c.condition)}</p><details><summary>Simulation check${c.source?' & reference':''}</summary><p>${esc(c.observed)}</p>${c.source?`<a href="${esc(c.source)}" target="_blank" rel="noreferrer">Skill interaction reference ↗</a>`:''}</details></section>`).join('')}</div>`:''}${r.units.map(u=>`<section class="causal-card"><h5>${esc(byId[u.id].name)}: what this slot contributes</h5>${(u.kit_explanation?.skills||[]).slice(0,2).map(k=>`<p><strong>${esc(k.skill)} · ${esc(k.mechanic)}</strong><br>${esc(k.explanation)}</p>`).join('')}<details><summary>${esc(byId[u.id].name)} · ${u.damage_share}% damage · ${u.gauge_share}% gauge</summary><ul>${u.reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>Skills ${Object.values(u.skills).join('/')} · Favorite item phase ${u.favorite_stage}. Burst times: ${u.burst_times.join(', ')||'none'}.</p>${u.assumptions.map(x=>`<p class="warning">${esc(x)}</p>`).join('')}${(u.kit_explanation?.skills||[]).map(k=>`<p><strong>${esc(k.skill)} · ${esc(k.mechanic)}</strong><br>${esc(k.explanation)}${k.recipients.length?'<br>Observed recipients: '+esc(k.recipients.join(', ')):''}${k.conditions.length?'<br>'+esc(k.conditions.join('; ')):''}</p>`).join('')}<p>${esc(u.kit_explanation?.coverage||'')}</p></details></section>`).join('')}<details><summary>Technical buff log · ${r.synergies.length} links</summary><p>These are actual buff recipients in the simulated rotation. Activation counts include refreshes.</p>${r.synergies.map(x=>`<p><strong>${esc(byId[x.source].name)} → ${esc(byId[x.target].name)}: ${esc(x.effect)}</strong><br>${x.count} activations / refreshes; first at ${x.first}s. ${esc(x.qualification)}</p>`).join('')||'<p>No tracked cross-unit buffs activated.</p>'}</details><details><summary>Selection evidence and limits</summary><p>${esc(report.selection?.objective||'')} ${esc(report.selection?.method||'Manually selected team; no alternative search performed.')}</p><p>${esc(report.selection?.optimality||'')}</p>${report.selection?.neighborhood_checks?.length?`<p>${report.selection.neighborhood_checks.length} full-duration replacement checks after screening owned alternatives. Results are selected using the stated encounter objective.</p>`:''}${report.selection?.rotation_checks?.length?`<p>Compared ${report.selection.rotation_checks.length} full-duration burst priority orders across the selected teams. The best valid order for the encounter objective is retained.</p>`:''}${(report.selection?.full_duration_finalists||[]).map((x,i)=>`<p>Full-duration candidate ${i+1}: ${fmt(x.damage)} combined damage — ${x.members.map(team=>team.map(n=>esc(byId[n].name)).join(', ')).join(' / ')}</p>`).join('')}${(report.selection?.replacement_checks||[]).filter(x=>x.squad===report.teams.indexOf(t)+1).map(x=>`<p><strong>${esc(byId[x.outgoing].name)} → ${esc(byId[x.incoming].name)}</strong>: ${x.status==='tested'?`${x.delta_pct>0?'+':''}${x.delta_pct}% team damage versus the pre-replacement team; ${x.selected?'replacement selected':'replacement not selected'}. Other squads were held fixed.`:`Excluded: ${esc(x.reason)}`}</p>`).join('')}<p>Full Burst starts: ${r.rotation.full_burst_times.join(', ')||'none'}. Largest gap between starts: ${r.rotation.largest_gap}s.</p><ul>${r.unverified.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details></section>`}
function renderLocalGuidance(t){
  const g=t.search_guidance;if(!g)return '';
  const names=ids=>ids.map(n=>esc(byId[n]?.name||n)).join(' → ');
  return '<details><summary>Synergy preferences and verified burst priority</summary><p>Local preferences help choose which teams to test first. Your builds and simulated encounter results decide the result.</p>'+
    g.pairs.map(p=>'<p><strong>'+names(p.members)+'</strong>: '+esc(p.reason)+'</p>').join('')+
    Object.entries(g.burst_priority).filter(([stage,ids])=>ids.length).map(([stage,ids])=>'<p>Burst '+esc(stage)+': '+names(ids)+'</p>').join('')+
    '<p>Priority within each burst stage; cooldowns determine who casts on each cycle.</p></details>';
}

function renderKitDependencies(t){const rows=t.kit_dependencies||[];if(!rows.length)return '';return `<details class="support-plan"><summary>Partner requirements and activation</summary><p>These checks apply to individual skills. A teammate being present does not guarantee the right target, timing or uptime.</p>${rows.map(r=>`<p><strong>${esc(byId[r.unit]?.name||r.unit)} · ${esc(r.kind.replaceAll('_',' '))}</strong>: ${esc(r.status)}<br>Available enablers: ${r.present_providers.map(n=>esc(byId[n]?.name||n)).join(', ')||'none'} · ${r.activations} observed activations${r.providers.length&&!r.present_providers.length?'<br>Eligible owned options: '+r.providers.map(n=>esc(byId[n]?.name||n)).join(', '):''}</p>`).join('')}</details>`}

function renderBurstRotation(t){const r=t.burst_rotation;if(!r)return '';return `<details class="support-plan"><summary>Full Burst duration and cooldown coverage</summary><p>${r.uptime_pct}% Full Burst uptime · ${r.full_burst_seconds}s in Full Burst. Intervals between starts: ${r.intervals.join(', ')||'insufficient cycles'} seconds.</p>${r.support_stages.map(s=>`<p><strong>B${s.stage}: ${esc(s.status)}</strong> · ${s.members.map((n,i)=>`${esc(byId[n]?.name||n)} (${s.cooldowns[i]}s cooldown)`).join(', ')}<br>Largest observed stage delay: ${s.largest_delay}s.</p>`).join('')}<p>${r.full_bursts.map(w=>`${w.start}–${w.end}s: ${esc(byId[w.unit]?.name||w.unit||'Full Burst')}, ${w.seconds}s${w.complete?'':' (fight ended)'}`).join('<br>')}</p><p>Longer Full Burst does not automatically extend fixed-duration skill buffs. Shorter Full Burst only allows faster rotations when gauge and cooldowns are ready. Team damage is compared over the whole fight.</p><p>${esc(r.policy)}</p></details>`}

function applyBossElement(p){const required=p.barrier_element,field=$('element');if(required){field.value=required;}else if(field.dataset.bossRequired){field.value='Any';}field.disabled=Boolean(required);field.dataset.bossRequired=required||'';$('elementLabel').textContent=required?'Boss-required damage element':'Required DPS element';$('elementHelp').textContent=p.id==='museum-mother-whale'?'Electric is required on every team. Actual barrier damage and summon clearing are simulated; this variant has no timed circle QTE.':required?`${required} is required automatically on every team for this boss. ${p.automatic_mechanics?'Actual circle damage and deadlines are simulated across all classes and Burst stages.':'Element presence alone does not establish a QTE pass.'}`:'Optional damage preference. Other units can use any element.';}

function bindSquadTabs(){const tabs=Array.from($('resultContent').querySelectorAll('[data-squad]'));function select(index,focus=false){selectedSquad=index;tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1;$('squadPanel'+i).hidden=i!==index;});if(focus)tabs[index].focus({preventScroll:true});$('squadDeck').scrollIntoView({block:'start',behavior:'instant'});}tabs.forEach((tab,i)=>{tab.onclick=()=>select(i);tab.onkeydown=e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;else if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();select(next,true);};});}

function renderSquadChecks(team,index){const names=Object.fromEntries(Object.entries(byId).map(([n,c])=>[n,c.name]));const currentParts=bosses.find(b=>b.id===report.settings.boss_id)?.critical_parts;const checkSettings={...report.settings,encounter:{...report.settings.encounter,critical_parts:report.settings.encounter?.critical_parts||currentParts}};const items=squadCheckItems(team,checkSettings,names);const icons={pass:'✓',fail:'✕',warn:'!',unknown:'?',info:'i'};return `<section class="squad-checks" aria-label="Squad ${index+1} checks"><div class="squad-check-heading"><h4>Squad checks</h4><small>Select a check for its evidence</small></div><div class="squad-check-row">${items.map(c=>`<button type="button" class="squad-check check-${c.state}" aria-expanded="false" aria-controls="squadCheckDetail${index}" data-check-detail="${esc(c.detail)}" aria-label="${esc(c.label+': '+c.value)}"><span class="check-icon" aria-hidden="true">${icons[c.state]}</span><span><strong>${esc(c.label)}</strong><small>${esc(c.value)}</small></span></button>`).join('')}</div><p id="squadCheckDetail${index}" class="squad-check-detail" role="status" hidden></p></section>`;}
function bindSquadChecks(){$('resultContent').querySelectorAll('[data-check-detail]').forEach(button=>{button.onclick=()=>{const section=button.closest('.squad-checks'),output=section.querySelector('.squad-check-detail'),open=button.getAttribute('aria-expanded')!=='true';section.querySelectorAll('[data-check-detail]').forEach(b=>b.setAttribute('aria-expanded','false'));button.setAttribute('aria-expanded',String(open));output.hidden=!open;output.textContent=open?button.dataset.checkDetail:'';};});}

$('resultContent').addEventListener('click',e=>{const button=e.target.closest('[data-feedback]');if(button&&report)feedbackUI.open(report,Number(button.dataset.feedback));});


function renderSpecialGuide(p){
 if(!p.id.startsWith('special-')||!p.guidance)return '';
 const g=p.guidance;
 return `<details class="ex-guide" open><summary>EX plan for this boss</summary><p>${esc(g.summary)}</p><p><strong>Red circles (QTE)</strong><br>${esc(g.qte_tip)}</p><p><strong>Stay alive</strong><br>${esc(g.survival_tip)}</p><small>All units fight at level 200. Your gear and skills still matter. Aim for a better reward stage as your roster improves.</small><p><a href="${esc(g.source)}" target="_blank" rel="noreferrer">Boss guide ↗</a></p></details>`;
}

function renderSpecialOutcome(team){
 const f=team.encounter_timeline;if(!f?.special_interception)return '';
 const failures=(f.checks||[]).filter(c=>c.status==='failed');
 const advice=failures.length?'A circle check was missed. Inspect its deadline below and try more opening damage, faster burst cycling or a different shooter.':f.stop_reason?'The run stopped at a squad death. Inspect the incoming attacks and cover log, then try protection or healing suited to this boss.':f.target_reached?'The modeled team reached the maximum reward stage. Use the targeting and cover plan when trying it in game.':'The squad completed the requested time. Compare the next build or team by reward stage and the recorded survival checks.';
 return `<section class="ex-result${f.stop_reason?' ex-stopped':''}"><strong>Reward stage ${esc(f.reward_stage)} / 9 · ${f.target_reached?'maximum reached in model':f.stop_reason?'run stopped in model':'modeled result'} · ${esc(f.simulated_until)}s</strong><p>${esc(advice)}</p>${f.next_reward_damage!=null?`<p>Next reward stage: ${fmt(Math.max(0,f.next_reward_damage-f.boss_hp_damage))} more boss HP damage.</p>`:''}<small>QTE means breaking every red circle before its timer ends. A green result describes this simulation; gameplay calibration is still incomplete.</small></section>`;
}
